export const DEFAULT_LIFE={configured:false,mode:'fulltime',workStart:540,workEnd:1020,workDays:[0,1,2,3,4],remoteDays:[2,4],commute:45,sleepStart:1380,sleepEnd:420,remoteBudget:45,workshopBudget:240,normalSpeed:240,awaySpeed:480,autoSpeed:true,pauseOnReturn:false,backgroundProgress:true};
export const classicWork=t=>{const m=t%1440;return Math.floor(t/1440)%7<5&&((m>=510&&m<750)||(m>=810&&m<1050));};
const bounded=(n,min,max,fallback)=>Number.isFinite(Number(n))?Math.max(min,Math.min(max,Math.round(Number(n)))):fallback;
export function normalizeLife(input){const p=input&&typeof input==='object'?input:{},a={...DEFAULT_LIFE};for(const k of ['workStart','workEnd','sleepStart','sleepEnd'])a[k]=bounded(p[k],0,1439,a[k]);if(a.workEnd<=a.workStart){a.workStart=540;a.workEnd=1020;}if(a.sleepStart===a.sleepEnd){a.sleepStart=1380;a.sleepEnd=420;}a.autoSpeed=p.autoSpeed!==false;a.pauseOnReturn=p.pauseOnReturn===true;a.backgroundProgress=p.backgroundProgress!==false;a.mode=p.mode==='job'?'job':'fulltime';a.configured=p.configured===true;a.commute=bounded(p.commute,0,180,a.commute);a.remoteBudget=bounded(p.remoteBudget,0,90,a.remoteBudget);a.workshopBudget=bounded(p.workshopBudget,60,480,a.workshopBudget);a.normalSpeed=[60,240,480,1440].includes(Number(p.normalSpeed))?Number(p.normalSpeed):240;a.awaySpeed=[60,240,480,1440,7200].includes(Number(p.awaySpeed))?Number(p.awaySpeed):480;a.workDays=Array.isArray(p.workDays)?[...new Set(p.workDays.filter(d=>Number.isInteger(d)&&d>=0&&d<7))]:[...a.workDays];a.remoteDays=Array.isArray(p.remoteDays)?[...new Set(p.remoteDays.filter(d=>a.workDays.includes(d)))]:a.remoteDays.filter(d=>a.workDays.includes(d));return a;}
function within(m,a,b){return a<b?m>=a&&m<b:m>=a||m<b;}
export function presence(s,time=s.time){
 const p=s.life||DEFAULT_LIFE,m=Math.floor(time%1440),day=Math.floor(time/1440)%7,sameDay=Math.floor(time/1440)===Math.floor(s.time/1440),used=sameDay?(s.dayStats.humanMinutes||0):0,remoteUsed=sameDay?(s.dayStats.remoteMinutes||0):0;
 if(p.configured&&within(m,p.sleepStart,p.sleepEnd))return {kind:'sleep',locked:true,canWork:false,label:'Au pays des rêves',detail:'Tu dors. Les machines déjà lancées continuent si elles y sont autorisées.'};
 if(p.mode==='job'&&p.workDays.includes(day)){
  if(p.remoteDays.includes(day)){if(within(m,p.workStart,p.workEnd))return {kind:'remote',locked:false,canWork:remoteUsed<p.remoteBudget&&used<p.workshopBudget,label:'En télétravail',remaining:Math.max(0,p.remoteBudget-remoteUsed),detail:'Petites interventions seulement : '+Math.max(0,p.remoteBudget-remoteUsed)+' min encore disponibles aujourd’hui.'};}
  else if(m>=Math.max(0,p.workStart-p.commute)&&m<Math.min(1440,p.workEnd+p.commute))return {kind:'away',locked:true,canWork:false,label:'Au travail, ailleurs',detail:'Trajet et emploi extérieur : l’atelier attend ton retour. Les impressions lancées continuent.'};
 }
 const window=p.mode==='fulltime'?classicWork(time):true,limit=p.mode==='fulltime'?480:p.workshopBudget;
 if(window&&used<limit)return {kind:'atelier',locked:false,canWork:true,label:'À l’atelier',remaining:limit-used,detail:(limit-used)+' min de travail personnel disponibles aujourd’hui.'};
 return {kind:'rest',locked:false,canWork:false,label:'Temps libre',detail:used>=limit?'Ton budget de travail pour l’atelier est utilisé. Tu peux consulter les commandes.':'Les tâches reprendront pendant tes horaires d’atelier.'};
}
export function nextPresenceChange(s){const kind=presence(s).kind;for(let i=1;i<=8*1440;i++)if(presence(s,s.time+i).kind!==kind)return s.time+i;return s.time+1440;}
export function remoteAction(s,minutes=3){const p=presence(s);if(p.locked)return {ok:false,message:'Tu es absent ou endormi. Attends ton retour.'};if(p.kind==='remote'){if(p.remaining<minutes)return {ok:false,message:'Ton temps d’intervention en télétravail est épuisé.'};s.dayStats.remoteMinutes=(s.dayStats.remoteMinutes||0)+minutes;s.dayStats.humanMinutes+=minutes;if(s.analytics)s.analytics.humanMinutes+=minutes;}return {ok:true};}

const manualActions=new Set(['accept','decline','cancel-confirm','ship','cart-checkout','supply','campaign','website','buy-mode','grid-place','move','sell','service','part','practice']);
const physicalActions=new Set(['buy-mode','grid-place','move','sell','service','part','practice']);
export function actionAvailability(s,action){const p=presence(s);if(p.locked&&manualActions.has(action))return {ok:false,message:p.kind==='sleep'?'Ton artisan dort. Tu peux observer, changer la vitesse et ouvrir les paramètres. Les tâches attendront le réveil.':'Ton artisan est au travail. Les vues, la vitesse et les paramètres restent accessibles ; les interventions attendront son retour.'};if(p.kind==='remote'&&physicalActions.has(action))return {ok:false,message:'En télétravail, seules les petites interventions sont possibles. L’aménagement et l’entretien attendent ton temps libre.'};return {ok:true};}
export function canRunHumanTask(s,task=s.worker,p=presence(s)){if(!p.canWork||!task)return false;if(p.kind!=='remote')return true;if(task.kind==='loading'||task.kind==='research'||task.kind==='listing')return true;if(task.kind==='design')return (s.orders.find(o=>o.id===task.orderId)?.design??1)<=.3;return false;}
